import Root from './mask-input.svelte';

export type { MaskInputChildProps, MaskInputProps, MaskInputRootProps } from './mask-input.svelte';

export {
	MASK_INPUT_VALIDATION_MODES,
	MaskInputState,
	type MaskInputStateProps,
	type MaskInputValidationMode
} from './mask-input.svelte.js';

// The `phone-input` reuse surface (FR-017): the pattern table and the mask/unmask/caret maths, all
// pure and rune-free, so another component can import them without rendering a field.
export {
	applyCurrencyMask,
	applyMask,
	applyPercentageMask,
	DEFAULT_CURRENCY,
	DEFAULT_LOCALE,
	fromUnmaskedIndex,
	getCurrencyCaretPosition,
	getPatternCaretPosition,
	getUnmaskedValue,
	isCurrencyAtEnd,
	isCurrencyMask,
	MASK_PATTERN_KEYS,
	MASK_PATTERNS,
	resolveMaskPattern,
	toUnmaskedIndex,
	type MaskPattern,
	type MaskPatternKey,
	type TransformOptions,
	type ValidateOptions
} from './mask-engine.js';

export {
	Root,
	//
	Root as MaskInput
};

import type {
	ClipboardEventHandler,
	CompositionEventHandler,
	FocusEventHandler,
	FormEventHandler,
	HTMLInputAttributes,
	KeyboardEventHandler
} from 'svelte/elements';

import {
	applyMask,
	CURRENCY_PERCENTAGE_SYMBOLS,
	fromUnmaskedIndex,
	getCurrencyCaretPosition,
	getPatternCaretPosition,
	getUnmaskedValue,
	isCurrencyAtEnd,
	isCurrencyMask,
	NUMERIC_MASK_PATTERNS,
	resolveMaskPattern,
	toUnmaskedIndex,
	type MaskPattern,
	type MaskPatternKey,
	type TransformOptions,
	type ValidateOptions
} from './mask-engine.js';

/** Counts the `#` value slots of a pattern; module-level so its `lastIndex` never leaks. */
const HASH_PATTERN = /#/g;

/** When `onValidate` runs, mirroring `react-hook-form`'s modes. */
export const MASK_INPUT_VALIDATION_MODES = [
	'onChange',
	'onBlur',
	'onSubmit',
	'onTouched',
	'all'
] as const;

/** When `onValidate` runs. See {@link MASK_INPUT_VALIDATION_MODES}. */
export type MaskInputValidationMode = (typeof MASK_INPUT_VALIDATION_MODES)[number];

/** A DOM event whose `currentTarget` is known to be the masked `<input>`. */
type MaskInputEvent<E extends Event> = E & { currentTarget: EventTarget & HTMLInputElement };

/**
 * Everything {@link MaskInputState} needs from the component. Every reactive value arrives as a
 * getter function so the class keeps tracking it; `setValue` is the one place the value is written.
 */
export type MaskInputStateProps = {
	getValue: () => string;
	/** Assigns the component's `value`. Notification is the caller's job, through `getOnValueChange`. */
	setValue: (value: string) => void;
	getMask: () => MaskPatternKey | MaskPattern | undefined;
	getCurrency: () => string;
	getLocale: () => string;
	getValidationMode: () => MaskInputValidationMode;
	getPlaceholder: () => string | undefined | null;
	getMaskPlaceholder: () => string | undefined;
	getWithoutMask: () => boolean;
	getDisabled: () => boolean;
	getReadonly: () => boolean;
	getInputMode: () => HTMLInputAttributes['inputmode'];
	getMaxLength: () => number | undefined | null;
	getMin: () => string | number | undefined | null;
	getMax: () => string | number | undefined | null;
	getOnValueChange: () => ((maskedValue: string, unmaskedValue: string) => void) | undefined;
	getOnValidate: () => ((isValid: boolean, unmaskedValue: string) => void) | undefined;
	getOninput: () => FormEventHandler<HTMLInputElement> | undefined | null;
	getOnfocus: () => FocusEventHandler<HTMLInputElement> | undefined | null;
	getOnblur: () => FocusEventHandler<HTMLInputElement> | undefined | null;
	getOnkeydown: () => KeyboardEventHandler<HTMLInputElement> | undefined | null;
	getOnpaste: () => ClipboardEventHandler<HTMLInputElement> | undefined | null;
	getOncompositionstart: () => CompositionEventHandler<HTMLInputElement> | undefined | null;
	getOncompositionend: () => CompositionEventHandler<HTMLInputElement> | undefined | null;
};

function toNumber(value: string | number | undefined | null): number | undefined {
	if (value === undefined || value === null) return undefined;
	return typeof value === 'string' ? parseFloat(value) : value;
}

/**
 * The behaviour of `<MaskInput>`: what the field displays, where the caret goes after the value has
 * been reformatted, and when validation runs.
 *
 * Every handler resolves the element from `event.currentTarget` rather than from a stored `ref`
 * (divergence D-05), which is what keeps the `child` snippet behaviour-complete.
 */
export class MaskInputState {
	// The `$derived` fields below are lazy at runtime (evaluated only when read), but svelte-check's
	// static analysis cannot see that and flags the field as used before its constructor assignment.
	#props!: MaskInputStateProps;

	/** Whether the field currently holds focus; drives the mask placeholder swap. */
	focused = $state(false);
	/** Whether an IME composition is in progress; masking is held back until it ends. */
	composing = $state(false);
	/** Whether the field has been blurred at least once; drives the `onTouched` mode. */
	touched = $state(false);

	/** The active pattern: the table entry for a key, or the object the caller passed. */
	readonly maskPattern = $derived(resolveMaskPattern(this.#props.getMask()));

	/** The currency/locale pair handed to every transform and formatter. */
	readonly transformOpts: TransformOptions = $derived({
		currency: this.#props.getCurrency(),
		locale: this.#props.getLocale()
	});

	/** The bounds handed to the pattern's `validate`, parsed out of the `min`/`max` attributes. */
	readonly validateOpts: ValidateOptions = $derived({
		min: toNumber(this.#props.getMin()),
		max: toNumber(this.#props.getMax())
	});

	/** The placeholder to render right now, per the resolution table in the component's docs. */
	readonly placeholderValue = $derived.by(() => {
		const placeholder = this.#props.getPlaceholder() ?? undefined;
		const maskPlaceholder = this.#props.getMaskPlaceholder();

		if (this.#props.getWithoutMask()) return placeholder;

		if (placeholder && maskPlaceholder) {
			return this.focused ? maskPlaceholder : placeholder;
		}

		if (maskPlaceholder) {
			return this.focused ? maskPlaceholder : undefined;
		}

		return placeholder;
	});

	/** The masked string the `<input>` shows. The component is the only writer of `element.value`. */
	readonly displayValue = $derived.by(() => {
		const value = this.#props.getValue();
		const maskPattern = this.maskPattern;

		if (this.#props.getWithoutMask() || !maskPattern || !value) return value ?? '';

		const unmasked = getUnmaskedValue({
			value,
			transform: maskPattern.transform,
			...this.transformOpts
		});
		return applyMask({
			value: unmasked,
			pattern: maskPattern.pattern,
			...this.transformOpts,
			mask: this.#props.getMask()
		});
	});

	/** How many value slots the pattern has, or `undefined` for `Intl`-formatted patterns. */
	readonly tokenCount = $derived.by(() => {
		const maskPattern = this.maskPattern;
		if (!maskPattern || CURRENCY_PERCENTAGE_SYMBOLS.test(maskPattern.pattern)) return undefined;
		return maskPattern.pattern.match(HASH_PATTERN)?.length ?? 0;
	});

	/**
	 * The emitted `maxlength`. A pattern with fixed slots caps the field at its rendered length;
	 * everything else — including a `#`-less custom pattern, whose `tokenCount` is a falsy `0` —
	 * falls back to the caller's `maxlength`.
	 */
	readonly calculatedMaxLength = $derived(
		this.tokenCount ? this.maskPattern?.pattern.length : (this.#props.getMaxLength() ?? undefined)
	);

	/** The emitted `inputmode`: the caller's wins, else one derived from the mask key. */
	readonly calculatedInputMode = $derived.by((): HTMLInputAttributes['inputmode'] => {
		const inputMode = this.#props.getInputMode();
		if (inputMode) return inputMode;
		if (!this.maskPattern) return undefined;

		const mask = this.#props.getMask();
		if (mask === 'currency' || mask === 'percentage' || mask === 'ipv4') {
			return 'decimal';
		}

		if (typeof mask === 'string' && NUMERIC_MASK_PATTERNS.test(mask)) {
			return 'numeric';
		}
		return undefined;
	});

	constructor(props: MaskInputStateProps) {
		this.#props = props;
	}

	/**
	 * Whether `onValidate` should run for this trigger.
	 *
	 * `touched` is a parameter rather than a plain read of `this.touched` so `onblur` can pass the
	 * value from *before* it marked the field touched — which is what React's stale-closure
	 * `useCallback` does upstream, and what makes the first blur validate in `onTouched` mode.
	 */
	shouldValidate(trigger: 'change' | 'blur', touched: boolean = this.touched): boolean {
		if (!this.#props.getOnValidate() || !this.maskPattern?.validate) return false;

		switch (this.#props.getValidationMode()) {
			case 'onChange':
				return trigger === 'change';
			case 'onBlur':
				return trigger === 'blur';
			case 'onSubmit':
				return false;
			case 'onTouched':
				return touched ? trigger === 'change' : trigger === 'blur';
			case 'all':
				return true;
			default:
				return trigger === 'change';
		}
	}

	/** Runs the pattern's `validate` and reports the verdict. */
	runValidate(unmaskedValue: string) {
		const onValidate = this.#props.getOnValidate();
		const validate = this.maskPattern?.validate;
		if (onValidate && validate) {
			onValidate(validate(unmaskedValue, this.validateOpts), unmaskedValue);
		}
	}

	/**
	 * The single commit path (divergence D-10): assign the value, then notify. Upstream writes state
	 * only in some branches and calls `onValueChange` in others, which would let `bind:value` and the
	 * derived display value go stale here.
	 */
	#commit(maskedValue: string, unmaskedValue: string) {
		this.#props.setValue(maskedValue);
		this.#props.getOnValueChange()?.(maskedValue, unmaskedValue);
	}

	oninput(event: MaskInputEvent<Event>) {
		this.#props.getOninput()?.(event);
		if (event.defaultPrevented) return;

		const element = event.currentTarget;
		const inputValue = element.value;

		// Mid-composition the raw text is kept as-is and nobody is notified; `oncompositionend`
		// masks and commits it once the IME is done.
		if (this.composing) {
			this.#props.setValue(inputValue);
			return;
		}

		const maskPattern = this.maskPattern;

		if (this.#props.getWithoutMask() || !maskPattern) {
			if (this.shouldValidate('change')) this.#props.getOnValidate()?.(true, inputValue);
			this.#commit(inputValue, inputValue);
			return;
		}

		const mask = this.#props.getMask();
		const unmaskedValue = getUnmaskedValue({
			value: inputValue,
			transform: maskPattern.transform,
			...this.transformOpts
		});
		const newValue = applyMask({
			value: unmaskedValue,
			pattern: maskPattern.pattern,
			...this.transformOpts,
			mask
		});

		if (newValue !== inputValue) {
			const oldCursorPosition = element.selectionStart ?? 0;

			element.value = newValue;

			const currentUnmasked = getUnmaskedValue({
				value: newValue,
				transform: maskPattern.transform,
				...this.transformOpts
			});
			const previousUnmasked = getUnmaskedValue({
				value: this.#props.getValue(),
				transform: maskPattern.transform,
				...this.transformOpts
			});

			let newCursorPosition = CURRENCY_PERCENTAGE_SYMBOLS.test(maskPattern.pattern)
				? getCurrencyCaretPosition({
						newValue,
						mask,
						transformOpts: this.transformOpts,
						oldCursorPosition,
						oldValue: inputValue,
						previousUnmasked
					})
				: getPatternCaretPosition({
						newValue,
						maskPattern,
						currentUnmasked,
						oldCursorPosition,
						oldValue: inputValue,
						previousUnmasked
					});

			if (isCurrencyMask({ mask, pattern: maskPattern.pattern })) {
				if (mask === 'currency') {
					if (!isCurrencyAtEnd(this.transformOpts)) {
						newCursorPosition = Math.max(1, newCursorPosition);
					}
				} else {
					newCursorPosition = Math.max(1, newCursorPosition);
				}
			} else if (maskPattern.pattern.includes('%')) {
				newCursorPosition = Math.min(newValue.length - 1, newCursorPosition);
			}

			newCursorPosition = Math.min(newCursorPosition, newValue.length);

			element.setSelectionRange(newCursorPosition, newCursorPosition);
		}

		if (this.shouldValidate('change')) this.runValidate(unmaskedValue);
		this.#commit(newValue, unmaskedValue);
	}

	onfocus(event: MaskInputEvent<FocusEvent>) {
		this.#props.getOnfocus()?.(event);
		if (event.defaultPrevented) return;

		this.focused = true;
	}

	onblur(event: MaskInputEvent<FocusEvent>) {
		this.#props.getOnblur()?.(event);
		if (event.defaultPrevented) return;

		this.focused = false;

		const wasTouched = this.touched;
		if (!wasTouched) this.touched = true;

		if (this.shouldValidate('blur', wasTouched)) {
			const currentValue = event.currentTarget.value;
			const maskPattern = this.maskPattern;
			const unmaskedValue = maskPattern
				? getUnmaskedValue({
						value: currentValue,
						transform: maskPattern.transform,
						...this.transformOpts
					})
				: currentValue;
			this.runValidate(unmaskedValue);
		}
	}

	oncompositionstart(event: MaskInputEvent<CompositionEvent>) {
		this.#props.getOncompositionstart()?.(event);
		if (event.defaultPrevented) return;

		this.composing = true;
	}

	oncompositionend(event: MaskInputEvent<CompositionEvent>) {
		this.#props.getOncompositionend()?.(event);
		if (event.defaultPrevented) return;

		this.composing = false;

		const inputValue = event.currentTarget.value;
		const maskPattern = this.maskPattern;

		if (!maskPattern || this.#props.getWithoutMask()) {
			if (this.shouldValidate('change')) this.#props.getOnValidate()?.(true, inputValue);
			this.#commit(inputValue, inputValue);
			return;
		}

		const unmasked = getUnmaskedValue({
			value: inputValue,
			transform: maskPattern.transform,
			...this.transformOpts
		});
		const masked = applyMask({
			value: unmasked,
			pattern: maskPattern.pattern,
			...this.transformOpts,
			mask: this.#props.getMask()
		});

		if (this.shouldValidate('change')) this.runValidate(unmasked);
		this.#commit(masked, unmasked);
	}

	onpaste(event: MaskInputEvent<ClipboardEvent>) {
		this.#props.getOnpaste()?.(event);
		if (event.defaultPrevented) return;

		// Divergence D-08: upstream omits this guard and would rewrite a read-only field's value.
		if (this.#props.getDisabled() || this.#props.getReadonly()) return;

		const maskPattern = this.maskPattern;
		if (this.#props.getWithoutMask() || !maskPattern) return;

		const mask = this.#props.getMask();
		if (mask === 'ipv4') return;

		const target = event.currentTarget;
		const pastedData = event.clipboardData?.getData('text');
		if (!pastedData) return;

		event.preventDefault();

		const currentValue = target.value;
		const selectionStart = target.selectionStart ?? 0;
		const selectionEnd = target.selectionEnd ?? 0;

		const newInputValue =
			currentValue.slice(0, selectionStart) + pastedData + currentValue.slice(selectionEnd);

		const unmasked = getUnmaskedValue({
			value: newInputValue,
			transform: maskPattern.transform,
			...this.transformOpts
		});
		const newMaskedValue = applyMask({
			value: unmasked,
			pattern: maskPattern.pattern,
			...this.transformOpts,
			mask
		});

		target.value = newMaskedValue;

		// Upstream returns from both symbol branches without notifying; the value is still committed
		// here so `bind:value` and `displayValue` cannot go stale behind the element (D-10).
		if (isCurrencyMask({ mask, pattern: maskPattern.pattern })) {
			const caret = isCurrencyAtEnd(this.transformOpts)
				? newMaskedValue.search(/\s*[^\d\s]+$/)
				: newMaskedValue.length;
			target.setSelectionRange(caret, caret);
			this.#props.setValue(newMaskedValue);
			return;
		}

		if (maskPattern.pattern.includes('%')) {
			const caret = newMaskedValue.length - 1;
			target.setSelectionRange(caret, caret);
			this.#props.setValue(newMaskedValue);
			return;
		}

		let position = 0;
		let count = 0;
		for (let i = 0; i < maskPattern.pattern.length && i < newMaskedValue.length; i++) {
			if (maskPattern.pattern[i] === '#') {
				count++;
				if (count <= unmasked.length) {
					position = i + 1;
				}
			}
		}

		target.setSelectionRange(position, position);

		if (this.shouldValidate('change')) this.runValidate(unmasked);
		this.#commit(newMaskedValue, unmasked);
	}

	onkeydown(event: MaskInputEvent<KeyboardEvent>) {
		this.#props.getOnkeydown()?.(event);
		if (event.defaultPrevented) return;

		// Divergence D-08: upstream omits this guard and would rewrite a read-only field's value.
		if (this.#props.getDisabled() || this.#props.getReadonly()) return;

		const maskPattern = this.maskPattern;
		if (this.#props.getWithoutMask() || !maskPattern) return;

		const mask = this.#props.getMask();
		if (mask === 'ipv4') return;

		// `Intl`-formatted values are re-derived from scratch on `input`, so the native edit is left
		// alone; so is any non-collapsed selection, which the browser deletes as a whole.
		const isSymbolPattern =
			mask === 'currency' ||
			mask === 'percentage' ||
			maskPattern.pattern.includes('$') ||
			maskPattern.pattern.includes('€') ||
			maskPattern.pattern.includes('%');

		if (event.key === 'Backspace') {
			const target = event.currentTarget;
			const cursorPosition = target.selectionStart ?? 0;
			const selectionEnd = target.selectionEnd ?? 0;
			const currentValue = target.value;

			if (isSymbolPattern) return;
			if (cursorPosition !== selectionEnd) return;

			if (cursorPosition > 0) {
				const charBeforeCursor = currentValue[cursorPosition - 1];

				if (charBeforeCursor) {
					event.preventDefault();

					const unmaskedIndex = toUnmaskedIndex({
						masked: currentValue,
						pattern: maskPattern.pattern,
						caret: cursorPosition
					});

					if (unmaskedIndex > 0) {
						const currentUnmasked = getUnmaskedValue({
							value: currentValue,
							transform: maskPattern.transform,
							...this.transformOpts
						});
						const nextUnmasked =
							currentUnmasked.slice(0, unmaskedIndex - 1) + currentUnmasked.slice(unmaskedIndex);
						const nextMasked = applyMask({
							value: nextUnmasked,
							pattern: maskPattern.pattern,
							...this.transformOpts,
							mask
						});

						target.value = nextMasked;
						const nextCaret = fromUnmaskedIndex({
							masked: nextMasked,
							pattern: maskPattern.pattern,
							unmaskedIndex: unmaskedIndex - 1
						});

						target.setSelectionRange(nextCaret, nextCaret);

						this.#commit(nextMasked, nextUnmasked);
					}
					return;
				}
			}
		}

		if (event.key === 'Delete') {
			const target = event.currentTarget;
			const cursorPosition = target.selectionStart ?? 0;
			const selectionEnd = target.selectionEnd ?? 0;
			const currentValue = target.value;

			if (isSymbolPattern) return;
			if (cursorPosition !== selectionEnd) return;

			if (cursorPosition < currentValue.length) {
				const charAtCursor = currentValue[cursorPosition];

				if (charAtCursor) {
					event.preventDefault();

					const unmaskedIndex = toUnmaskedIndex({
						masked: currentValue,
						pattern: maskPattern.pattern,
						caret: cursorPosition
					});

					const currentUnmasked = getUnmaskedValue({
						value: currentValue,
						transform: maskPattern.transform,
						...this.transformOpts
					});

					if (unmaskedIndex < currentUnmasked.length) {
						const nextUnmasked =
							currentUnmasked.slice(0, unmaskedIndex) + currentUnmasked.slice(unmaskedIndex + 1);
						const nextMasked = applyMask({
							value: nextUnmasked,
							pattern: maskPattern.pattern,
							...this.transformOpts,
							mask
						});

						target.value = nextMasked;
						const nextCaret = fromUnmaskedIndex({
							masked: nextMasked,
							pattern: maskPattern.pattern,
							unmaskedIndex
						});

						target.setSelectionRange(nextCaret, nextCaret);

						this.#commit(nextMasked, nextUnmasked);
					}
					return;
				}
			}
		}
	}
}

/**
 * The mask/format/caret engine behind `<MaskInput>`, kept free of runes and of the DOM so another
 * component (a future `phone-input`) can import the pattern table and the formatting helpers without
 * rendering anything, and so the module is safe to evaluate on the server.
 *
 * A 1:1 translation of the pure half of
 * `.reference/diceui/docs/registry/bases/radix/ui/mask-input.tsx`.
 */

const PAST_YEARS_LIMIT = 120;
const FUTURE_YEARS_LIMIT = 10;

/** The currency used when none is supplied, and the fallback when `Intl` rejects the caller's. */
export const DEFAULT_CURRENCY = 'USD';
/** The locale used when none is supplied, and the fallback when `Intl` rejects the caller's. */
export const DEFAULT_LOCALE = 'en-US';

/** Mask keys whose slots only ever hold digits, and which therefore get `inputmode="numeric"`. */
export const NUMERIC_MASK_PATTERNS =
	/^(phone|zipCode|zipCodeExtended|ssn|ein|time|date|creditCard|creditCardExpiry)$/;

/** Patterns carrying one of these symbols are formatted by `Intl`, not slot-by-slot. */
export const CURRENCY_PERCENTAGE_SYMBOLS = /[€$%]/;

type CurrencySymbols = {
	currency: string;
	decimal: string;
	group: string;
};

const formattersCache = new Map<string, Intl.NumberFormat>();
const currencyAtEndCache = new Map<string, boolean>();
const currencySymbolsCache = new Map<string, CurrencySymbols>();
const daysInMonthCache = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31] as const;

const REGEX_CACHE = {
	digitsOnly: /^\d+$/,
	nonDigits: /\D/g,
	nonAlphaNumeric: /[^A-Z0-9]/gi,
	nonNumericDot: /[^0-9.]/g,
	nonCurrencyChars: /[^\d.,]/g,
	hashPattern: /#/g,
	currencyAtEnd: /\d\s*[^\d\s]+$/,
	percentageChars: /[^\d.]/g,
	phone: /^\d{10}$/,
	ssn: /^\d{9}$/,
	zipCode: /^\d{5}$/,
	zipCodeExtended: /^\d{9}$/,
	isbn: /^\d{13}$/,
	ein: /^\d{9}$/,
	time: /^\d{4}$/,
	creditCard: /^\d{13,19}$/,
	creditCardExpiry: /^\d{4}$/,
	licensePlate: /^[A-Z0-9]{6}$/,
	macAddress: /^[A-F0-9]{12}$/,
	currencyValidation: /^\d+(\.\d{1,2})?$/,
	ipv4Segment: /^\d{1,3}$/
} as const;

/** Options handed to a pattern's `transform` function. */
export type TransformOptions = {
	/** ISO 4217 currency code, used by the currency transform. */
	currency?: string;
	/** BCP 47 locale tag, used by the currency transform. */
	locale?: string;
};

/** Options handed to a pattern's `validate` function. */
export type ValidateOptions = {
	/** Lower bound for numeric patterns such as `percentage`. */
	min?: number;
	/** Upper bound for numeric patterns such as `percentage`. */
	max?: number;
};

/** A mask definition: the slot template plus how to unmask and how to judge a value. */
export type MaskPattern = {
	/** The slot template, where `#` is a value slot and every other character is a literal. */
	pattern: string;
	/** Turns what the user typed into the raw, unformatted value. Defaults to "digits only". */
	transform?: (value: string, opts?: TransformOptions) => string;
	/** Decides whether an unmasked value is complete and well-formed. */
	validate?: (value: string, opts?: ValidateOptions) => boolean;
};

/** The keys of the built-in {@link MASK_PATTERNS} table. */
export type MaskPatternKey =
	| 'phone'
	| 'ssn'
	| 'date'
	| 'time'
	| 'creditCard'
	| 'creditCardExpiry'
	| 'zipCode'
	| 'zipCodeExtended'
	| 'currency'
	| 'percentage'
	| 'licensePlate'
	| 'ipv4'
	| 'macAddress'
	| 'isbn'
	| 'ein';

function getCachedFormatter(
	locale: string | undefined,
	opts: Intl.NumberFormatOptions
): Intl.NumberFormat {
	const { currency, minimumFractionDigits = 0, maximumFractionDigits = 2 } = opts;

	const key = `${locale}|${currency}|${minimumFractionDigits}|${maximumFractionDigits}`;

	if (!formattersCache.has(key)) {
		try {
			formattersCache.set(
				key,
				new Intl.NumberFormat(locale, {
					style: 'currency',
					currency,
					...opts
				})
			);
		} catch {
			formattersCache.set(
				key,
				new Intl.NumberFormat(DEFAULT_LOCALE, {
					style: 'currency',
					currency: DEFAULT_CURRENCY,
					...opts
				})
			);
		}
	}

	const formatter = formattersCache.get(key);
	if (!formatter) {
		throw new Error(`Failed to create formatter for ${key}`);
	}
	return formatter;
}

function getCachedCurrencySymbols(opts: TransformOptions): CurrencySymbols {
	const { locale, currency } = opts;

	const key = `${locale}|${currency}`;
	const cached = currencySymbolsCache.get(key);
	if (cached) {
		return cached;
	}

	let currencySymbol = '$';
	let decimalSeparator = '.';
	let groupSeparator = ',';

	try {
		const formatter = getCachedFormatter(locale, {
			currency,
			minimumFractionDigits: 0,
			maximumFractionDigits: 2
		});
		const parts = formatter.formatToParts(1234.5);
		const currencyPart = parts.find((part) => part.type === 'currency');
		const decimalPart = parts.find((part) => part.type === 'decimal');
		const groupPart = parts.find((part) => part.type === 'group');

		if (currencyPart) currencySymbol = currencyPart.value;
		if (decimalPart) decimalSeparator = decimalPart.value;
		if (groupPart) groupSeparator = groupPart.value;
	} catch {
		// Keep defaults
	}

	const symbols: CurrencySymbols = {
		currency: currencySymbol,
		decimal: decimalSeparator,
		group: groupSeparator
	};
	currencySymbolsCache.set(key, symbols);
	return symbols;
}

/** Whether this locale/currency pair renders the symbol after the number (`1.234 €`). */
export function isCurrencyAtEnd(opts: TransformOptions): boolean {
	const { locale, currency } = opts;

	const key = `${locale}|${currency}`;
	const cached = currencyAtEndCache.get(key);
	if (cached !== undefined) {
		return cached;
	}

	try {
		const formatter = getCachedFormatter(locale, {
			currency,
			minimumFractionDigits: 0,
			maximumFractionDigits: 0
		});
		const sample = formatter.format(123);
		const result = REGEX_CACHE.currencyAtEnd.test(sample);
		currencyAtEndCache.set(key, result);
		return result;
	} catch {
		currencyAtEndCache.set(key, false);
		return false;
	}
}

/** Whether the active mask formats money, by key or by the symbol in its pattern. */
export function isCurrencyMask(opts: {
	mask: MaskPatternKey | MaskPattern | undefined;
	pattern?: string;
}): boolean {
	const { mask, pattern } = opts;

	return (
		mask === 'currency' || Boolean(pattern && (pattern.includes('$') || pattern.includes('€')))
	);
}

/** The built-in mask table, in upstream declaration order. */
export const MASK_PATTERNS: Record<MaskPatternKey, MaskPattern> = {
	phone: {
		pattern: '(###) ###-####',
		transform: (value) => value.replace(REGEX_CACHE.nonDigits, ''),
		validate: (value) => REGEX_CACHE.phone.test(value.replace(REGEX_CACHE.nonDigits, ''))
	},
	ssn: {
		pattern: '###-##-####',
		transform: (value) => value.replace(REGEX_CACHE.nonDigits, ''),
		validate: (value) => REGEX_CACHE.ssn.test(value.replace(REGEX_CACHE.nonDigits, ''))
	},
	date: {
		pattern: '##/##/####',
		transform: (value) => value.replace(REGEX_CACHE.nonDigits, ''),
		validate: (value) => {
			const cleaned = value.replace(REGEX_CACHE.nonDigits, '');
			if (cleaned.length !== 8) return false;
			const month = parseInt(cleaned.substring(0, 2), 10);
			const day = parseInt(cleaned.substring(2, 4), 10);
			const year = parseInt(cleaned.substring(4, 8), 10);

			const currentYear = new Date().getFullYear();
			const minYear = currentYear - PAST_YEARS_LIMIT;
			const maxYear = currentYear + FUTURE_YEARS_LIMIT;
			if (month < 1 || month > 12 || day < 1 || year < minYear || year > maxYear) return false;

			const maxDays =
				month === 2 && ((year % 4 === 0 && year % 100 !== 0) || year % 400 === 0)
					? 29
					: (daysInMonthCache[month - 1] ?? 31);

			return day <= maxDays;
		}
	},
	time: {
		pattern: '##:##',
		transform: (value) => value.replace(REGEX_CACHE.nonDigits, ''),
		validate: (value) => {
			const cleaned = value.replace(REGEX_CACHE.nonDigits, '');
			if (!REGEX_CACHE.time.test(cleaned)) return false;
			const hours = parseInt(cleaned.substring(0, 2), 10);
			const minutes = parseInt(cleaned.substring(2, 4), 10);
			return hours <= 23 && minutes <= 59;
		}
	},
	creditCard: {
		pattern: '#### #### #### ####',
		transform: (value) => value.replace(REGEX_CACHE.nonDigits, ''),
		validate: (value) => {
			const cleaned = value.replace(REGEX_CACHE.nonDigits, '');
			if (!REGEX_CACHE.creditCard.test(cleaned)) return false;

			let sum = 0;
			let isEven = false;
			for (let i = cleaned.length - 1; i >= 0; i--) {
				const digitChar = cleaned[i];
				if (!digitChar) continue;
				let digit = parseInt(digitChar, 10);
				if (isEven) {
					digit *= 2;
					if (digit > 9) {
						digit -= 9;
					}
				}
				sum += digit;
				isEven = !isEven;
			}
			return sum % 10 === 0;
		}
	},
	creditCardExpiry: {
		pattern: '##/##',
		transform: (value) => value.replace(REGEX_CACHE.nonDigits, ''),
		validate: (value) => {
			const cleaned = value.replace(REGEX_CACHE.nonDigits, '');
			if (!REGEX_CACHE.creditCardExpiry.test(cleaned)) return false;

			const month = parseInt(cleaned.substring(0, 2), 10);
			const year = parseInt(cleaned.substring(2, 4), 10);

			if (month < 1 || month > 12) return false;

			const now = new Date();
			const currentYear = now.getFullYear();
			const currentMonth = now.getMonth() + 1;

			const fullYear = year <= 75 ? 2000 + year : 1900 + year;

			if (fullYear < currentYear || (fullYear === currentYear && month < currentMonth)) {
				return false;
			}

			const maxYear = currentYear + 50;
			if (fullYear > maxYear) {
				return false;
			}

			return true;
		}
	},
	zipCode: {
		pattern: '#####',
		transform: (value) => value.replace(REGEX_CACHE.nonDigits, ''),
		validate: (value) => REGEX_CACHE.zipCode.test(value.replace(REGEX_CACHE.nonDigits, ''))
	},
	zipCodeExtended: {
		pattern: '#####-####',
		transform: (value) => value.replace(REGEX_CACHE.nonDigits, ''),
		validate: (value) => REGEX_CACHE.zipCodeExtended.test(value.replace(REGEX_CACHE.nonDigits, ''))
	},
	currency: {
		pattern: '$###,###.##',
		transform: (value, { currency = DEFAULT_CURRENCY, locale = DEFAULT_LOCALE } = {}) => {
			let localeDecimalSeparator = '.';

			try {
				const formatter = getCachedFormatter(locale, {
					currency,
					minimumFractionDigits: 0,
					maximumFractionDigits: 2
				});
				const parts = formatter.formatToParts(1234.5);
				const decimalPart = parts.find((part) => part.type === 'decimal');

				if (decimalPart) localeDecimalSeparator = decimalPart.value;
			} catch {
				// Keep defaults
			}

			const cleaned = value.replace(REGEX_CACHE.nonCurrencyChars, '');

			const dotIndex = cleaned.indexOf('.');
			const commaIndex = cleaned.indexOf(',');

			let hasDecimalSeparator = false;
			let decimalIndex = -1;

			if (localeDecimalSeparator === ',') {
				const lastCommaIndex = cleaned.lastIndexOf(',');
				if (lastCommaIndex !== -1) {
					const afterComma = cleaned.substring(lastCommaIndex + 1);
					if (afterComma.length <= 2 && /^\d*$/.test(afterComma)) {
						hasDecimalSeparator = true;
						decimalIndex = lastCommaIndex;
					}
				}

				if (!hasDecimalSeparator && dotIndex !== -1) {
					const afterDot = cleaned.substring(dotIndex + 1);
					if (afterDot.length <= 2 && /^\d*$/.test(afterDot)) {
						hasDecimalSeparator = true;
						decimalIndex = dotIndex;
					}
				}

				if (!hasDecimalSeparator && cleaned.length >= 4) {
					const match = cleaned.match(/^(\d+)\.(\d{3})(\d{1,2})$/);
					if (match) {
						const [, beforeDot, thousandsPart, decimalPart] = match;
						const integerPart = (beforeDot ?? '') + (thousandsPart ?? '');
						const result = `${integerPart}.${decimalPart}`;
						return result;
					}
				}
			} else {
				const lastDotIndex = cleaned.lastIndexOf('.');
				if (lastDotIndex !== -1) {
					const afterDot = cleaned.substring(lastDotIndex + 1);
					if (afterDot.length <= 2 && /^\d*$/.test(afterDot)) {
						hasDecimalSeparator = true;
						decimalIndex = lastDotIndex;
					}
				}

				if (!hasDecimalSeparator && commaIndex !== -1) {
					const afterComma = cleaned.substring(commaIndex + 1);
					const looksLikeThousands = commaIndex <= 3 && afterComma.length >= 3;
					if (!looksLikeThousands && afterComma.length <= 2 && /^\d*$/.test(afterComma)) {
						hasDecimalSeparator = true;
						decimalIndex = commaIndex;
					}
				}
			}

			if (hasDecimalSeparator && decimalIndex !== -1) {
				const beforeDecimal = cleaned.substring(0, decimalIndex).replace(/[.,]/g, '');
				const afterDecimal = cleaned.substring(decimalIndex + 1).replace(/[.,]/g, '');

				if (afterDecimal === '') {
					const result = `${beforeDecimal}.`;
					return result;
				}

				const result = `${beforeDecimal}.${afterDecimal.substring(0, 2)}`;
				return result;
			}

			const digitsOnly = cleaned.replace(/[.,]/g, '');
			return digitsOnly;
		},
		validate: (value) => {
			if (!REGEX_CACHE.currencyValidation.test(value)) return false;
			const num = parseFloat(value);
			return !Number.isNaN(num) && num >= 0;
		}
	},
	percentage: {
		pattern: '##.##%',
		transform: (value) => {
			const cleaned = value.replace(REGEX_CACHE.percentageChars, '');
			const parts = cleaned.split('.');
			if (parts.length > 2) {
				return `${parts[0]}.${parts.slice(1).join('')}`;
			}
			if (parts[1] && parts[1].length > 2) {
				return `${parts[0]}.${parts[1].substring(0, 2)}`;
			}
			return cleaned;
		},
		validate: (value, opts = {}) => {
			const num = parseFloat(value);
			const min = opts.min ?? 0;
			const max = opts.max ?? 100;
			return !Number.isNaN(num) && num >= min && num <= max;
		}
	},
	licensePlate: {
		pattern: '###-###',
		transform: (value) => value.replace(REGEX_CACHE.nonAlphaNumeric, '').toUpperCase(),
		validate: (value) => REGEX_CACHE.licensePlate.test(value)
	},
	ipv4: {
		pattern: '###.###.###.###',
		transform: (value) => value.replace(REGEX_CACHE.nonNumericDot, ''),
		validate: (value) => {
			if (value.includes('.')) {
				const segments = value.split('.');
				if (segments.length > 4) return false;

				return segments.every((segment) => {
					if (segment === '') return true;
					if (!REGEX_CACHE.ipv4Segment.test(segment)) return false;
					const num = parseInt(segment, 10);
					return num <= 255;
				});
			} else {
				if (!REGEX_CACHE.digitsOnly.test(value)) return false;
				if (value.length > 12) return false;

				const chunks = [];
				for (let i = 0; i < value.length; i += 3) {
					chunks.push(value.substring(i, i + 3));
				}

				if (chunks.length > 4) return false;

				return chunks.every((chunk) => {
					const num = parseInt(chunk, 10);
					return num >= 0 && num <= 255;
				});
			}
		}
	},
	macAddress: {
		pattern: '##:##:##:##:##:##',
		transform: (value) => value.replace(REGEX_CACHE.nonAlphaNumeric, '').toUpperCase(),
		validate: (value) => REGEX_CACHE.macAddress.test(value)
	},
	isbn: {
		pattern: '###-#-###-#####-#',
		transform: (value) => value.replace(REGEX_CACHE.nonDigits, ''),
		validate: (value) => REGEX_CACHE.isbn.test(value.replace(REGEX_CACHE.nonDigits, ''))
	},
	ein: {
		pattern: '##-#######',
		transform: (value) => value.replace(REGEX_CACHE.nonDigits, ''),
		validate: (value) => REGEX_CACHE.ein.test(value.replace(REGEX_CACHE.nonDigits, ''))
	}
};

/** The built-in mask keys, in {@link MASK_PATTERNS} declaration order. */
export const MASK_PATTERN_KEYS = Object.keys(MASK_PATTERNS) as readonly MaskPatternKey[];

/** Resolves the `mask` prop to a {@link MaskPattern}: a key looks the table up, an object is itself. */
export function resolveMaskPattern(
	mask: MaskPatternKey | MaskPattern | undefined
): MaskPattern | undefined {
	if (typeof mask === 'string') {
		return MASK_PATTERNS[mask];
	}
	return mask;
}

/** Formats an already-unmasked value against a pattern, currency or percentage rules included. */
export function applyMask(opts: {
	value: string;
	pattern: string;
	currency?: string;
	locale?: string;
	mask?: MaskPatternKey | MaskPattern;
}): string {
	const { value, pattern, currency, locale, mask } = opts;

	const cleanValue = value;

	if (pattern.includes('$') || pattern.includes('€') || mask === 'currency') {
		return applyCurrencyMask({
			value: cleanValue,
			currency: currency ?? DEFAULT_CURRENCY,
			locale: locale ?? DEFAULT_LOCALE
		});
	}

	if (pattern.includes('%')) {
		return applyPercentageMask(cleanValue);
	}

	if (mask === 'ipv4') {
		return cleanValue;
	}

	const maskedChars: string[] = [];
	let valueIndex = 0;

	for (let i = 0; i < pattern.length && valueIndex < cleanValue.length; i++) {
		const patternChar = pattern[i];
		const valueChar = cleanValue[valueIndex];

		if (patternChar === '#' && valueChar) {
			maskedChars.push(valueChar);
			valueIndex++;
		} else if (patternChar) {
			maskedChars.push(patternChar);
		}
	}

	return maskedChars.join('');
}

/** Formats a raw numeric string as money through `Intl.NumberFormat`. */
export function applyCurrencyMask(opts: {
	value: string;
	currency?: string;
	locale?: string;
}): string {
	const { value, currency = DEFAULT_CURRENCY, locale = DEFAULT_LOCALE } = opts;

	if (!value) return '';

	const {
		currency: currencySymbol,
		decimal: decimalSeparator,
		group: groupSeparator
	} = getCachedCurrencySymbols({ locale, currency });

	const normalizedValue = value
		.replace(new RegExp(`\\${groupSeparator.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}`, 'g'), '')
		.replace(decimalSeparator, '.');

	const parts = normalizedValue.split('.');
	const integerPart = parts[0] ?? '';
	const fractionalPart = parts[1] ?? '';

	if (!integerPart && !fractionalPart) return '';

	const intValue = integerPart ?? '0';
	const fracValue = fractionalPart.slice(0, 2);

	const num = Number(`${intValue}.${fracValue ?? ''}`);

	if (Number.isNaN(num)) {
		const cleanedDigits = value.replace(/[^\d]/g, '');
		if (!cleanedDigits) return '';
		return `${currencySymbol}${cleanedDigits}`;
	}

	const hasExplicitDecimal = value.includes('.') || value.includes(decimalSeparator);

	try {
		const formatter = getCachedFormatter(locale, {
			currency,
			minimumFractionDigits: fracValue ? fracValue.length : 0,
			maximumFractionDigits: 2
		});
		const result = formatter.format(num);

		if (hasExplicitDecimal && !fracValue) {
			if (result.match(/^[^\d\s]+/)) {
				const finalResult = result.replace(/(\d)$/, `$1${decimalSeparator}`);
				return finalResult;
			} else {
				const finalResult = result.replace(/(\d)(\s*)([^\d\s]+)$/, `$1${decimalSeparator}$2$3`);
				return finalResult;
			}
		}

		return result;
	} catch {
		const formattedInt = intValue.replace(/\B(?=(\d{3})+(?!\d))/g, groupSeparator);
		let result = `${currencySymbol}${formattedInt}`;
		if (hasExplicitDecimal) {
			result += `${decimalSeparator}${fracValue}`;
		}

		return result;
	}
}

/** Appends the percent sign and clamps the fraction to two digits. */
export function applyPercentageMask(value: string): string {
	if (!value) return '';

	const parts = value.split('.');
	let result = parts[0] ?? '0';

	if (value.includes('.')) {
		result += `.${(parts[1] ?? '').substring(0, 2)}`;
	}

	return `${result}%`;
}

/** Strips the mask from a displayed value, through the pattern's `transform` or digits-only. */
export function getUnmaskedValue(opts: {
	value: string;
	currency?: string;
	locale?: string;
	transform?: (value: string, opts?: TransformOptions) => string;
}): string {
	const { value, transform, currency, locale } = opts;

	return transform
		? transform(value, { currency, locale })
		: value.replace(REGEX_CACHE.nonDigits, '');
}

/** How many value slots sit before `caret` in a masked string. */
export function toUnmaskedIndex(opts: { masked: string; pattern: string; caret: number }): number {
	const { masked, pattern, caret } = opts;

	let idx = 0;
	for (let i = 0; i < caret && i < masked.length && i < pattern.length; i++) {
		if (pattern[i] === '#') {
			idx++;
		}
	}

	return idx;
}

/** Where the caret sits in a masked string once `unmaskedIndex` value slots have been passed. */
export function fromUnmaskedIndex(opts: {
	masked: string;
	pattern: string;
	unmaskedIndex: number;
}): number {
	const { masked, pattern, unmaskedIndex } = opts;

	let seen = 0;
	for (let i = 0; i < masked.length && i < pattern.length; i++) {
		if (pattern[i] === '#') {
			seen++;
			if (seen === unmaskedIndex) {
				return i + 1;
			}
		}
	}

	return masked.length;
}

/** Where the caret belongs after an `Intl`-formatted currency or percentage value was rewritten. */
export function getCurrencyCaretPosition(opts: {
	newValue: string;
	mask: MaskPatternKey | MaskPattern | undefined;
	transformOpts: TransformOptions;
	oldCursorPosition?: number;
	oldValue?: string;
	previousUnmasked?: string;
}): number {
	const { newValue, mask, transformOpts, oldCursorPosition, oldValue, previousUnmasked } = opts;

	if (oldCursorPosition !== undefined && oldValue && previousUnmasked !== undefined) {
		if (oldCursorPosition < oldValue.length) {
			const digitsBeforeCursor = oldValue.substring(0, oldCursorPosition).replace(/\D/g, '').length;

			let digitCount = 0;
			for (let i = 0; i < newValue.length; i++) {
				if (/\d/.test(newValue[i] ?? '')) {
					digitCount++;
					if (digitCount === digitsBeforeCursor) {
						return i + 1;
					}
				}
			}
		}
	}

	if (mask === 'currency') {
		const currencyAtEnd = isCurrencyAtEnd(transformOpts);
		if (currencyAtEnd) {
			const match = newValue.match(/(\d)\s*([^\d\s]+)$/);
			if (match?.[1]) {
				return newValue.lastIndexOf(match[1]) + 1;
			} else {
				return newValue.length;
			}
		} else {
			return newValue.length;
		}
	} else {
		return newValue.length;
	}
}

/** Where the caret belongs after a slot pattern was rewritten. */
export function getPatternCaretPosition(opts: {
	newValue: string;
	maskPattern: MaskPattern;
	currentUnmasked: string;
	oldCursorPosition?: number;
	oldValue?: string;
	previousUnmasked?: string;
}): number {
	const { newValue, maskPattern, currentUnmasked, oldCursorPosition, oldValue, previousUnmasked } =
		opts;
	let position = 0;
	let unmaskedCount = 0;

	if (oldCursorPosition !== undefined && oldValue && previousUnmasked !== undefined) {
		const oldUnmaskedIndex = toUnmaskedIndex({
			masked: oldValue,
			pattern: maskPattern.pattern,
			caret: oldCursorPosition
		});

		if (oldCursorPosition < oldValue.length) {
			const targetUnmaskedIndex = Math.min(oldUnmaskedIndex, currentUnmasked.length);

			for (let i = 0; i < maskPattern.pattern.length && i < newValue.length; i++) {
				if (maskPattern.pattern[i] === '#') {
					unmaskedCount++;
					if (unmaskedCount <= targetUnmaskedIndex) {
						position = i + 1;
					}
				}
			}

			return position;
		}
	}

	for (let i = 0; i < maskPattern.pattern.length && i < newValue.length; i++) {
		if (maskPattern.pattern[i] === '#') {
			unmaskedCount++;
			if (unmaskedCount <= currentUnmasked.length) {
				position = i + 1;
			}
		}
	}

	return position;
}
